[InitializeOnLoad]public static class GridShiftV11Checks {
 static GridShiftV11Checks(){EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredPlayMode&&SessionState.GetBool("V11",false)){SessionState.SetBool("V11",false);var go=new GameObject("V11Checks");Object.DontDestroyOnLoad(go);go.AddComponent<GridShiftV11Runner>();}};}
 public static void Batch(){GridShiftV11Setup.Stage();EditorSceneManager.OpenScene("Assets/Scenes/MainMenu.unity");SessionState.SetBool("V11",true);EditorApplication.isPlaying=true;}
}
