.Instance.IsOpen,"ESC seguinte abre pausa");Find(PauseMenu.Instance.transform,"Salvar Jogo").onClick.Invoke();Find(saves.transform,"Salvar neste slot").onClick.Invoke();Check(GridShiftSavesUI.IsOpen,"salvamento manual exige confirmação de sobrescrita");Find(saves.transform,"Confirmar").onClick.Invoke();Check(GridShiftProfiles.Read(1,out var saved,out _)&&saved.companyName=="Empresa Alfa"&&saved.vehicles.Count==3,"save manual guarda empresa e frota completa");Check(!File.ReadAllText(slot1).Contains("V11-temporaria"),"senha não é gravada no save");PauseMenu.Instance.Close();yield return Until(()=>order.vehicleId!=null,15,"entrega recebe veículo compatível");Check(manager.Progression.Buy("capacity",out _),"upgrade usa saldo real");manager.TrackVehicle(order.vehicleId);Check(manager.GetComponent<DeliveryPersistence>().Save(),"salvar entrega em andamento");Check(GridShiftProfiles.Read(1,out saved,out _),"ler estado completo versionado");float savedMoney=saved.money;string orderId=order.id,vehicleId=order.vehicleId;var savedFleet=saved.vehicles.First(v=>v.id==vehicleId);yield return GridShiftSession.ReturnToMenu();yield return new WaitForSecondsRealtime(4);Check(DeliveryManager.Instance==null,"retorno ao menu encerra sessão anterior");GridShiftProfiles.Read(1,out saved,out _);Object.FindFirstObjectByType<GridShiftMainMenu>().StartSlot(saved,false);yield return Until(()=>DeliveryManager.Instance!=null&&DeliveryManager.Instance.GetComponent<DeliveryPersistence>().Ready&&!WorldSession.Instance.Busy&&SceneManager.GetActiveScene().name=="Office",90,"carregar restaura a cena Office e gerenciadores");manager=DeliveryManager.Instance;Check(manager.fleet.Count==3&&manager.orders.Count==1&&manager.orders[0].id==orderId,"recarregar não duplica veículos nem entregas");Check(Mathf.Abs(manager.Money-savedMoney)<.01f&&manager.Progression.Level("capacity")==1,"saldo e upgrade restaurados");Check(manager.TrackedVehicleId==vehicleId&&manager.Company.State.selectedMission==missionId,"rastreamentos persistem no save");var restored=manager.fleet.First(v=>v.id==vehicleId);Check(restored.Order!=null&&restored.Order.id==orderId&&GridShiftRouteIdentity.Of(restored.driver.RotaAtual)==savedFleet.routeId,"veículo retoma entrega em rota estável");office=Object.FindObjectsByType<PlayerMovement>(FindObjectsSortMode.None).First(p=>p.gameObject.scene.name=="Office");var terminal=Object.FindObjectsByType<ComputerInteraction>(FindObjectsSortMode.None).First(t=>t.gameObject.scene.name=="Office");terminal.EnterComputer();yield return Until(()=>terminal.UsingComputer&&!terminal.MovingCamera,6,"computador mantém zoom e painel nativo");Check(terminal.Operations!=null,"monitor exibe central Urban Flow nativa");if(GridShiftV12Checks.Enabled)yield return GridShiftV12Checks.Interface(terminal.Operations,office,"computer");terminal.Operations.Show("Financeiro");yield return Tap(Key.Escape);yield return Until(()=>!terminal.UsingComputer&&!terminal.MovingCamera,6,"ESC sai do computador e restaura câmera");WorldSession.Instance.RequestTransition("SampleScene",office.transform);yield return Until(()=>!WorldSession.Instance.Busy&&SceneManager.GetActiveScene().name=="SampleScene",40,"voltar à cidade preserva a sessão");var city=Object.FindObjectsByType<PlayerMovement>(FindObjectsSortMode.None).First(p=>p.gameObject.scene.name=="SampleScene");var hud=city.CameraTransform.GetComponentsInChildren<Canvas>(true).FirstOrDefault(c=>c.name=="DeliveryHUD");if(GridShiftV12Checks.Enabled)GridShiftV12Checks.Route(manager,restored);Check(hud!=null&&hud.enabled&&hud.gameObject.activeInHierarchy&&hud.GetComponent<CanvasGroup>().alpha>0,"HUD 3D reaparece após Office com avatar anteriormente inativo");Check(hud.GetComponentsInChildren<TMP_Text>().Any(t=>t.text.Contains(manager.Company.Missions.Selected.name)),"missão selecionada continua visível");GridShiftOperationsUI.Instance.Open("map");yield return new WaitForSecondsRealtime(.3f);Check(manager.TrackedVehicleId==vehicleId,"mapa ampliado preserva 