 yield return GridShiftSession.ReturnToMenu();yield return new WaitForSecondsRealtime(4);Check(GridShiftProfiles.Create(2,"Empresa Beta",false,out _),"criar Slot 02 não apaga Slot 01");Check(GridShiftProfiles.Read(1,out var alfa,out _)&&GridShiftProfiles.Read(2,out var beta,out _)&&alfa.money>0&&beta.money==0&&beta.orders.Count==0,"slots possuem progresso independente");Check(GridShiftProfiles.Create(3,"Recuperação",false,out _),"criar cenário de recuperação");var path3=GridShiftProfiles.SlotPath(3);GridShiftProfiles.Read(3,out var recovery,out _);recovery.money=10;DeliverySaveStore.WriteAt(path3,recovery);File.WriteAllText(path3,"{corrompido");Check(GridShiftProfiles.Read(3,out _,out bool recovered)&&recovered,"arquivo inválido recupera backup válido");Check(!GridShiftProfiles.Delete(3,false,out _)&&File.Exists(path3),"exclusão recusada sem confirmação");Check(GridShiftProfiles.Delete(3,true,out _)&&!File.Exists(path3)&&File.Exists(slot1),"exclusão confirmada afeta somente o slot escolhido");string profileA=GridShiftProfiles.ProfileId;GridShiftProfiles.Login("empresa-b@local","outra",out _);Check(GridShiftProfiles.ProfileId!=profileA&&GridShiftProfiles.List().All(s=>s==null),"perfis distintos não compartilham saves");Check(Object.FindObjectsByType<GridShiftNativeOperations>(FindObjectsInactive.Include,FindObjectsSortMode.None).Length==0,"interfaces da sessão encerrada são liberadas");
